            ['开检查', 'medical_record', '{"chief_complaint":{"symptom":"患者无不适主诉，要求开检查","duration":"1","unit":"小时","second_symptom":"","second_duration":"","second_unit":""},"history_present":{"informant":"患者自诉","duration":"1","unit":"小时","content":"要求开具相关检查，否认不适主诉","arrival_way":"自行来院"},"advice":"检查完毕后及时前往专科门诊就诊。"}', 'doctor', 0, 'published', 1],
            ['开药', 'medical_record', '{"chief_complaint":{"symptom":"患者有用药需求","duration":"1","unit":"小时","second_symptom":"","second_duration":"","second_unit":""},"history_present":{"informant":"患者自诉","duration":"1","unit":"小时","content":"有用药需求，既往有用药病史，否认不适主诉","arrival_way":"自行来院"},"advice":"请严格按照医嘱/药品说明书规律服药，注意休息，若有不适，及时前往我院门诊就诊。"}', 'doctor', 0, 'published', 1],

            // 知情同意书模板 (consent)
            ['手术知情同意书', 'consent', '{"content":"一、手术目的及必要性\n\n经临床评估及检查，患者目前诊断明确，具备明确的手术适应证。\n手术目的在于去除病灶、探查止血、纠正畸形、修复损伤或重建生理功能。保守治疗（若有）无法达到理想疗效或已无效。\n\n二、手术风险及可能发生的并发症\n任何手术均为侵入性医疗操作，存在不可预测的风险。受患者原发病严重程度、合并基础疾病（高血压、糖尿病、心肺功能不全等）、解剖变异及现有医学技术局限性影响，术中及术后可能发生以下风险与并发症：\n\n术中意外与麻醉风险：心搏骤停、严重心律失常、血压骤降、过敏性休克、恶性高热；麻醉相关风险详见《麻醉知情同意书》。\n\n大出血与脏器/神经损伤：术中血管破裂导致严重大出血或弥散性血管内凝血（DIC），必要时需输血抢救；周围邻近重要神经、血管或邻近脏器意外损伤，术后可能遗留相应功能障碍。\n\n术式改变或探查受限：术中探查若发现病变范围、性质与术前评估严重不符，或遇不可抗力风险，医师需根据术中情况改变拟定术式、扩大手术范围、或终止手术（必要时向家属术中紧急加签告知）。\n\n术后出血与血肿：创面活动性渗血或结扎线脱落导致继发性出血、血肿压迫，必要时需行二次急诊手术止血。\n\n术后感染：切口感染、深部组织脓肿、胸腹腔感染、肺部感染或泌尿系感染，严重者可引发败血症、感染性休克。\n\n血栓与栓塞性疾病：术后因卧床、创伤及血液高凝状态，可能并发深静脉血栓形成（DVT），栓子脱落可导致致死性肺动脉栓塞（PE）或脑梗死。\n\n切口与创面并发症：切口裂开、延迟愈合、脂肪液化、坏死，术后窦道形成或遗留增生性瘢痕、切口疝。\n\n吻合口/缝合口并发症（若涉及内脏手术）：吻合口瘘、破裂、狭窄、局部坏死，可能需长期引流、再次手术修复或造瘘。\n\n原发病复发或效果不达预期：术后病灶残留、复发，或因组织粘连、神经功能受损等导致原有症状未完全缓解。\n\n不可抗力与未知风险：突发严重急性心脑血管意外（急性心肌梗死、脑出血）、多器官功能衰竭等危及生命的情况。\n\n三、医患沟通与替代方案\n\n替代治疗方案：医师已说明其他可行方案（如保守药物治疗、介入治疗、严密观察等）及其利弊与局限性。\n\n植入物与耗材：术中若需使用人工材料、内固定物、止血材料等高值医用耗材，医师已告知其必要性及自费比例。","notice":"患者/委托人已知晓上述病情介绍与知情同意内容，医生已向我详细解释，我已完全理解，愿意承担可能出现风险及并发症，并遵从医嘱，配合治疗。","sections":["chief_complaint","present_illness","past_history","allergy_history","physical_exam","preliminary_diagnosis"]}', 'doctor', 0, 'published', 1],
            ['病重通知书', 'consent', '{"content":"一、病情告知\n患者目前病情严重，机体各系统功能处于不稳定状态。经本科室医护人员积极诊治，患者现出现以下严重病情变化或器官功能障碍风险：\n\n主要病情危重表现：_____________________________________________\n\n可能出现的严重后果及恶化趋势：\n\n病情突发恶化：病情可能在短时间内进一步进展、转为病危状态，随时可能出现血压骤降、严重心律失常、急性呼吸衰竭、急性心肌梗死或心脏骤停。\n\n多器官功能障碍：由于原发疾病进展或严重应激，可能并发严重感染、脓毒症休克、弥散性血管内凝血（DIC）、脑血管意外、急性肝肾功能衰竭或多器官功能障碍综合征（MODS）。\n\n不可逆损害与生命危险：即使医护人员全力救治，因个体病情严重性及现有医学技术局限性，患者仍可能面临不可逆的组织器官功能损伤，甚至随时危及生命。\n\n二、抢救与监护措施\n针对患者当前的严重病情，医疗团队已制定并正在实施积极的救治方案：\n\n密切监测生命体征，加强基础护理与脏器功能支持；\n随时根据病情变化调整药物方案、补充必要抢救用药；\n如遇病情急剧恶化，将根据抢救需要紧急实施吸痰、无创/有创机械通气（气管插管）、电除颤、深静脉置管、心肺复苏等抢救措施。","notice":"患者/委托人已知晓上述病情介绍与知情同意内容，医生已向我详细解释，我已完全理解，愿意承担可能出现风险及并发症，并遵从医嘱，配合治疗。","sections":["chief_complaint","present_illness","physical_exam","preliminary_diagnosis"]}', 'doctor', 0, 'published', 1],
            ['清创术知情同意书', 'consent', '{"content":"一、操作目的及拟实施方案\n拟行操作：清创术 / 清创缝合术 / 伤口探查术\n操作目的：清除创口内异物、坏死组织及污物，修整创缘，减少细菌负荷，促进伤口愈合，最大程度恢复外观与生理功能。\n\n二、手术风险及可能发生的并发症\n尽管医护人员会严格执行无菌操作及规范救治，但因创伤程度、污染情况及个体差异，操作中及操作后仍可能存在以下风险：\n\n麻醉意外及过敏反应：局部麻醉药可能引起局部红肿、皮疹，极罕见情况下可能出现过敏性休克、中枢神经系统或心血管毒性反应。\n\n术中情况：损伤深部重要神经、血管、肌腱或重要脏器，必要时需扩大创口探查或转手术室行专科手术。\n\n出血与血肿：术后创面可能继续渗血或形成皮下血肿，严重时需再次切开止血。\n\n伤口感染：污染较重、软组织挫伤严重或合并糖尿病等基础疾病者，术后发生局部化脓、蜂窝织炎甚至全身脓毒症的风险较高；必要时需拆开缝线引流。\n\n愈合不良或延迟愈合：创缘皮肤缺血坏死、裂开，可能导致换药周期延长，甚至需二次缝合或植皮。\n\n异物残留：微小、深在或非金属异物受解剖及视野限制，术中可能无法完全探查并取尽。\n\n瘢痕形成与功能障碍：愈合后会遗留不同程度的手术瘢痕（包括增生性瘢痕或瘢痕疙瘩）；若损伤关节或肌腱，后期可能遗留活动受限或感觉减退。\n\n其他风险：破伤风、狂犬病等特异性感染风险（需按医嘱注射相关疫苗/抗毒素）。","notice":"患者/委托人已知晓上述病情介绍与知情同意内容，医生已向我详细解释，我已完全理解，愿意承担可能出现风险及并发症，并遵从医嘱，配合治疗。","sections":["chief_complaint","present_illness","physical_exam","preliminary_diagnosis"]}', 'doctor', 0, 'published', 1],
            ['石膏固定须知', 'consent', '{"content":"一、石膏塑形与硬化期注意事项（前24~72小时）\n\n避免受压变形：石膏完全干固硬化需24至72小时（石膏绷带约24~48小时，高分子树脂夹板约需数小时）。在石膏未干透前，请勿随意按压，搬动患肢时应使用手掌平托，避免手指捏掐造成局部内凹压迫皮肤。\n\n促进干燥与保暖：石膏外不要覆盖厚重被褥，保持通风以利水分蒸发；冬季注意暴露肢体末端的保暖。\n\n二、居家体位与日常护理\n\n抬高患肢：卧床或坐位时，下肢石膏垫高使患肢高于心脏水平20~30厘米，上肢使用三角巾或前臂吊带悬吊胸前，以利静脉血液及淋巴回流，减轻局部肿胀与疼痛。\n\n严禁浸水防潮：保持石膏清洁干燥。沐浴时须用保鲜膜及防水套密封包扎；若石膏潮湿软化或污染，应及时回院更换。\n\n严禁自行填塞或伸入抓痒：肢体发痒时，切忌使用毛衣针、发夹或竹签伸入石膏内搔抓，以免划破皮肤引发难以察觉的皮下感染与溃烂。\n\n三、功能锻炼（预防肌肉萎缩与血栓）\n\n肌肉等长收缩：固定期间应尽早开展石膏内肌肉的规律收紧-放松训练（如大腿股四头肌收缩、小腿绷脚与勾脚）。\n\n未固定关节活动：主动活动石膏未固定的临近关节（如手指或脚趾屈伸、踝部外露者活动脚趾、前臂固定者活动肩肘关节），每日数次，每次15~20分钟。\n\n四、紧急预警症状（出现以下情况须立即复诊）\n石膏过紧可压迫血管神经导致骨筋膜室综合征或压疮，出现以下任一表现时切勿拖延，立即到急诊或骨科复查：\n\n血液循环障碍：患肢末端（手指/脚趾）出现苍白、青紫、发凉、发麻或感觉迟钝。\n\n剧烈进展性疼痛：石膏内出现持续性加重的烧灼样或搏动性剧痛，口服止痛药无法缓解，尤其是被动牵拉手指/脚趾时诱发剧痛。\n\n严重水肿：末梢肢体肿胀明显，活动严重受限。\n\n局部压迫坏死隐患：石膏某一点固定压痛明显，或闻及石膏内有异味、可见异常渗血渗液。\n\n石膏松动或破裂：伤口消肿后石膏明显变松晃动（起不到固定作用），或石膏发生断裂、变形。\n\n复诊提醒：请严格按照医生交代的时间（通常为固定后1周复查X光确认位置，4~6周评估骨愈合情况）定期回院复诊，严禁自行拆除、切割或修剪石膏。","notice":"患者/委托人已知晓上述病情介绍与知情同意内容，医生已向我详细解释，我已完全理解，愿意承担可能出现风险及并发症，并遵从医嘱，配合治疗。","sections":["chief_complaint","present_illness","physical_exam","preliminary_diagnosis"]}', 'doctor', 0, 'published', 1],
            ['气管插管知情同意书', 'consent', '{"content":"一、操作目的及拟实施方案\n\n拟行操作：经口气管插管术 / 经鼻气管插管术\n操作目的：建立人工气道，解除呼吸道梗阻，保持气道通畅；便于进行机械通气（呼吸机辅助呼吸）、清除呼吸道分泌物、实施心肺复苏或保障全麻手术安全。\n\n二、手术风险及可能发生的并发症\n气管插管是一项抢救及保障生命的侵入性操作。医护人员将严格按规范操作，但因患者病情严重程度、解剖结构变异（如困难气道、短颈、下颌后缩等）及个体差异，操作中及留置期间可能发生以下风险与并发症：\n\n操作中损伤：牙齿松动、脱落或折断（特别是已有松动牙或义齿者）；口唇、舌、咽喉壁、软腭黏膜擦伤、出血；声带水肿、充血或黏膜损伤。\n\n循环与神经系统应激反应：插管刺激可能引起严重交感神经兴奋或迷走神经反射，导致严重心律失常、血压骤升骤降，甚至诱发急性心肌梗死或心搏骤停。\n\n误吸与误入：胃内容物反流误吸入气道引起吸入性肺炎，甚至窒息；导管误入食道（若未能及时识别可致严重缺氧）。\n\n困难气道导致插管失败：若遇严重声门暴露困难、会厌水肿或畸形，可能出现多次插管失败，严重时需紧急行环甲膜穿刺/切开术或紧急气管切开术。\n\n下呼吸道及胸膜并发症：气胸、纵隔气肿；导管过深单侧肺通气导致肺不张。\n\n留置期间及拔管后并发症：\n导管意外脱出（非计划性拔管）、气道内分泌物或血块堵塞导管导致急性窒息；\n呼吸机相关性肺炎（VAP）等下呼吸道感染；\n气管黏膜缺血、坏死、溃疡，长期留置可能导致气管狭窄、气管软化或气管食管瘘；\n拔管后喉痉挛、声门下水肿致呼吸困难，或因喉返神经受损遗留声音嘶哑。\n\n替代治疗风险：若拒绝插管，可能因严重缺氧、二氧化碳潴留、呼吸道梗阻在极短时间内发生窒息、不可逆脑损伤乃至死亡。","notice":"患者/委托人已知晓上述病情介绍与知情同意内容，医生已向我详细解释，我已完全理解，愿意承担可能出现风险及并发症，并遵从医嘱，配合治疗。","sections":["chief_complaint","present_illness","physical_exam","preliminary_diagnosis"]}', 'doctor', 0, 'published', 1],
            ['门诊一般告知书', 'consent', '{"content":"一、诊疗与配合事项\n\n真实提供病史：为确保诊断与用药安全，请如实向医生提供既往病史、过敏史（药物/食物）、目前正在服用的药物、妊娠或哺乳状态及手术外伤史。因隐瞒病史导致的诊断偏差或不良反应由患者自行承担。\n\n检查与诊断局限性：门诊临床诊断需结合患者症状、体征及必要的辅助检查（血液检验、影像学、心电图等）。疾病在早期或发展过程中可能存在非典型表现，医学检查存在一定假阳性、假阴性率，需动态观察或进一步复查明确。\n\n药物治疗说明：请务必严格遵医嘱服药，不可擅自增减剂量或停药。任何药物均存在不同程度的不良反应风险（如皮疹、恶心、嗜睡等），用药期间若出现明显不适，请立即停药并就医。\n\n二、病情变化与随诊提醒\n\n动态观察与复诊：多数疾病的发展具有不确定性。经门诊初步处理或开药治疗后，若症状未见好转、进行性加重，或出现新发症状（如突发胸闷胸痛、剧烈腹痛、高热不退、抽搐、意识障碍等），须立即前往本院急诊科或就近医疗机构急诊就诊。\n\n特殊检查与侵入性操作：若需进一步进行注射、穿刺、内镜或其他侵入性操作，医务人员将在操作前另行评估并签署专项知情同意书。","notice":"患者/委托人已知晓上述病情介绍与知情同意内容，医生已向我详细解释，我已完全理解，愿意承担可能出现风险及并发症，并遵从医嘱，配合治疗。","sections":["chief_complaint","present_illness","preliminary_diagnosis"]}', 'doctor', 0, 'published', 1],

            // 护理记录模板 (nursing_record)
            ['一般护理记录', 'nursing_record', '{"content":"患者生命体征平稳，饮食可，二便通畅，配合治疗。"}', 'nurse', 0, 'published', 1],
            ['术后护理记录', 'nursing_record', '{"content":"术后患者生命体征监测正常，伤口无感染，活动受限需辅助。"}', 'nurse', 0, 'published', 1],
            ['危重患者护理记录', 'nursing_record', '{"content":"患者诊治中，持续监测生命体征，密切观察病情动态。"}', 'nurse', 0, 'published', 1],
            ['静脉输液护理记录', 'nursing_record', '{"content":"静脉输液过程中患者无不适，输液速度正常，密切观察穿针处。"}', 'nurse', 0, 'published', 1],

            // 嘱托模板 (order_note)
