    public function run() {
        $pdo = $this->pdo;
        $adminRow = $pdo->query("SELECT id, name FROM users WHERE role='admin' ORDER BY id LIMIT 1")->fetch(PDO::FETCH_ASSOC);
        $adminId = $adminRow ? (int)$adminRow['id'] : 1;
        $adminName = $adminRow ? (string)$adminRow['name'] : '系统管理员';

        // 旧版无意义的病历模板删除，仅保留开检查/开药
        $pdo->exec("DELETE FROM emr_templates WHERE type='medical_record' AND title IN ('入科病历','出科病历','门诊初诊模板')");
        $created = 0; $updated = 0;
        $stmt = $pdo->prepare('SELECT id FROM emr_templates WHERE title=? AND type=?');
        $upd = $pdo->prepare("UPDATE emr_templates SET scope='hospital', creator_id=?, creator_name=?, status='published', is_system=0, content_json=?, updated_at=? WHERE id=?");
        $ins = $pdo->prepare('INSERT INTO emr_templates(title, type, scope, creator_id, creator_name, status, is_system, content_json, created_at, updated_at) VALUES(?,?,?,?,?,?,0,?,?,?)');
        foreach ($this->defs as $T) {
            $stmt->execute(array($T[0], $T[1]));
            $tplId = $stmt->fetchColumn();
            if ($tplId) {
                // 已存在：转为管理员模板（is_system=0），同步内容/归属，管理员可编辑
                $upd->execute(array($adminId, $adminName, $T[2], now_str(), (int)$tplId));
                $updated++;
            } else {
                $ins->execute(array($T[0], $T[1], 'hospital', $adminId, $adminName, 'published', $T[2], now_str(), now_str()));
                $created++;
            }
        }
        $this->out('新增 ' . $created . ' / 同步 ' . $updated . ' 个模板（管理员模板可编辑）');
        return $created;
    }
}

$s = new TemplateSeeder();
$s->run();
